import sys, re
from xml.dom import minidom

path = "word/document.xml"
with open(path, encoding="utf-8") as f:
    content = f.read()

doc = minidom.parseString(content)

W = "http://schemas.openxmlformats.org/wordprocessingml/2006/main"

def q(tag):
    return f"{{{W}}}{tag}"

def text_of_para(p):
    parts = []
    for t in p.getElementsByTagName(q("t")):
        parts.append(t.firstChild.nodeValue if t.firstChild else "")
    for t in p.getElementsByTagName(q("delText")):
        parts.append(t.firstChild.nodeValue if t.firstChild else "")
    return "".join(parts)

body = doc.getElementsByTagName(q("body"))[0]
paras = body.getElementsByTagName(q("p"))
print(f"Total paragraphs: {len(paras)}")
seen_styles = {}
for i, p in enumerate(paras):
    pPr = p.getElementsByTagName(q("pPr"))
    style = ""
    if pPr:
        st = pPr[0].getElementsByTagName(q("pStyle"))
        if st:
            style = st[0].getAttribute(q("val"))
    txt = text_of_para(p).strip()
    if style:
        seen_styles[style] = seen_styles.get(style, 0) + 1
        print(f"[{i}] style={style!r} text={txt[:90]!r}")
print("Style counts:", seen_styles)

import os
from xml.dom import minidom

W = "http://schemas.openxmlformats.org/wordprocessingml/2006/main"


def q(name):
    return "{%s}%s" % (W, name)


BASE = os.path.dirname(os.path.abspath(__file__))
DOC = os.path.join(BASE, "word", "document.xml")


def para_text(p):
    parts = []
    for tag in (q("t"), q("delText")):
        for node in p.getElementsByTagName(tag):
            if node.firstChild and node.firstChild.nodeValue:
                parts.append(node.firstChild.nodeValue)
    return "".join(parts)


def is_headline(p):
    """A report headline: non-empty text with letters, none lowercase
    (excludes bullets, table rows, separators, and body sentences)."""
    text = para_text(p).strip()
    if not text:
        return False
    has_letter = any(ch.isalpha() for ch in text)
    has_lower = any(ch.islower() for ch in text)
    return has_letter and not has_lower


dom = minidom.parse(DOC)
body = dom.getElementsByTagName(q("body"))[0]
paras = body.getElementsByTagName(q("p"))

underlined = []
changed_runs = 0
for p in paras:
    if not is_headline(p):
        continue
    for r in p.getElementsByTagName(q("r")):
        if not r.getElementsByTagName(q("t")):
            continue  # no visible text to underline
        rprs = r.getElementsByTagName(q("rPr"))
        if not rprs:
            rpr = dom.createElementNS(W, "w:rPr")
            r.insertBefore(rpr, r.firstChild)
        else:
            rpr = rprs[0]
        if rpr.getElementsByTagName(q("u")):
            continue  # already underlined
        u = dom.createElementNS(W, "w:u")
        u.setAttributeNS(W, "w:val", "single")
        rpr.appendChild(u)
        changed_runs += 1
    underlined.append(para_text(p).strip())

with open(DOC, "wb") as fh:
    dom.writexml(fh, encoding="UTF-8")

for text in underlined:
    print("-", text)
print("Underlined %d headline paragraphs (%d runs)." % (len(underlined), changed_runs))

